      .handle("updateAction", ({ params, payload }) =>
        provide(
          Effect.gen(function* () {
            yield* requireSameOrigin;
            const member = yield* currentMember;
            return yield* updateAction(member, params.teamId, params.actionId, payload);
          }),
        ),
      ),
  );
};
